20: // LimaDir returns the absolute path of `~/.lima` (or $LIMA_HOME, if set).
21: //
22: // NOTE: We do not use `~/Library/Application Support/Lima` on macOS.
23: // We use `~/.lima` so that we can have enough space for the length of the socket path,
24: // which can be only 104 characters on macOS.
25: func LimaDir() (string, error) {
26: 	dir := os.Getenv("LIMA_HOME")
27: 	if dir == "" {
28: 		homeDir, err := os.UserHomeDir()
29: 		if err != nil {
30: 			return "", err
31: 		}
32: 		dir = filepath.Join(homeDir, DotLima)
33: 	}
34: 	if _, err := os.Stat(dir); errors.Is(err, os.ErrNotExist) {
35: 		return dir, nil
36: 	}
37: 	realdir, err := filepath.EvalSymlinks(dir)
38: 	if err != nil {
39: 		return "", fmt.Errorf("cannot evaluate symlinks in %q: %w", dir, err)
40: 	}
41: 	return realdir, nil
42: }
