80: // InstanceDir returns the instance dir.
81: // InstanceDir does not check whether the instance exists.
82: func InstanceDir(name string) (string, error) {
83: 	if err := ValidateInstName(name); err != nil {
84: 		return "", err
85: 	}
86: 	limaDir, err := LimaDir()
87: 	if err != nil {
88: 		return "", err
89: 	}
90: 	dir := filepath.Join(limaDir, name)
91: 	return dir, nil
