94: // ValidateInstName checks if the name is a valid instance name. For this it needs to
95: // be a valid identifier, and not end in .yml or .yaml (case insensitively).
96: func ValidateInstName(name string) error {
97: 	if err := identifiers.Validate(name); err != nil {
98: 		return fmt.Errorf("instance name %q is not a valid identifier: %w", name, err)
99: 	}
100: 	lower := strings.ToLower(name)
101: 	if strings.HasSuffix(lower, ".yml") || strings.HasSuffix(lower, ".yaml") {
102: 		return fmt.Errorf("instance name %q must not end with .yml or .yaml suffix", name)
103: 	}
104: 	return nil
105: }

